package com.node_modules.cofeshop;

import javafx.fxml.FXML;
import javafx.fxml.Initializable;
import javafx.scene.control.*;
import javafx.scene.control.cell.PropertyValueFactory;
import javafx.scene.layout.Pane;
import javafx.scene.layout.VBox;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;

import java.net.URL;
import java.util.ResourceBundle;

public class POS_Controller implements Initializable {

    @FXML
    private TableView<OrderItem> tableView;
    @FXML
    private TableColumn<OrderItem, String> itemColumn;
    @FXML
    private TableColumn<OrderItem, Integer> qtyColumn;
    @FXML
    private TableColumn<OrderItem, Double> priceColumn;

    @FXML
    private RadioButton qrisRadio;
    @FXML
    private RadioButton cashRadio;

    @FXML
    private Button iceButton;
    @FXML
    private Button hotButton;
    @FXML
    private Button normalButton;

    @FXML
    private Label amountLabel;
    @FXML
    private Label taxLabel;
    @FXML
    private Label paymentMethodLabel;
    @FXML
    private Label totalLabel;

    // Item cards elements
    @FXML
    private VBox[] itemCards;
    @FXML
    private Pane[] itemImages;
    @FXML
    private TextField[] itemQuantities;
    @FXML
    private Button[] minusButtons;
    @FXML
    private Button[] plusButtons;

    private int[] itemQuantitiesValues = new int[12];
    private String[] itemNames = { "Coffee", "Tea", "Juice", "Milk", "Water", "Soda", "Smoothie", "Latte",
            "Cappuccino", "Espresso", "Mocha", "Americano" };
    private double[] itemPrices = { 15000, 12000, 20000, 10000, 5000, 8000, 25000, 18000,
            18000, 15000, 22000, 16000 };

    private ObservableList<OrderItem> orderItems = FXCollections.observableArrayList();

    @Override
    public void initialize(URL url, ResourceBundle resourceBundle) {
        // Initialize table columns
        itemColumn.setCellValueFactory(new PropertyValueFactory<>("name"));
        qtyColumn.setCellValueFactory(new PropertyValueFactory<>("quantity"));
        priceColumn.setCellValueFactory(new PropertyValueFactory<>("price"));

        // Set the items for the table view
        tableView.setItems(orderItems);

        // Set up items and event handlers
        setupItems();
        setupCategoryButtons();
        setupPaymentMethods();

        // Initialize the calculation
        updateTotals();
    }

    private void setupItems() {
        // Periksa apakah array terhubung dengan benar
        System.out.println("plusButtons length: " + (plusButtons != null ? plusButtons.length : "null"));
        System.out.println("minusButtons length: " + (minusButtons != null ? minusButtons.length : "null"));
        System.out.println("itemQuantities length: " + (itemQuantities != null ? itemQuantities.length : "null"));

        // Pastikan event handler terpasang dengan benar
        for (int i = 0; i < plusButtons.length; i++) {
            final int index = i;
            if (plusButtons[i] != null) {
                System.out.println("Setting up plus button " + i);
                plusButtons[i].setOnAction(e -> {
                    System.out.println("Plus button " + index + " clicked");
                    itemQuantitiesValues[index]++;
                    itemQuantities[index].setText(String.valueOf(itemQuantitiesValues[index]));
                    updateOrderItem(index);
                    updateTotals();
                });
            }

            if (minusButtons[i] != null) {
                minusButtons[i].setOnAction(e -> {
                    if (itemQuantitiesValues[index] > 0) {
                        itemQuantitiesValues[index]--;
                        itemQuantities[index].setText(String.valueOf(itemQuantitiesValues[index]));
                        updateOrderItem(index);
                        updateTotals();
                    }
                });
            }
        }
    }

    private void setupCategoryButtons() {
        iceButton.setOnAction(e -> filterByCategory("ICE"));
        hotButton.setOnAction(e -> filterByCategory("HOT"));
        normalButton.setOnAction(e -> filterByCategory("NORMAL"));
    }

    private void setupQuantityButtons() {
        // Already handled in setupItems()
    }

    private void setupPaymentMethods() {
        qrisRadio.setOnAction(e -> {
            paymentMethodLabel.setText("QRIS");
            updateTotals();
        });

        cashRadio.setOnAction(e -> {
            paymentMethodLabel.setText("Cash");
            updateTotals();
        });
    }

    private void updateOrderItem(int index) {
        String itemName = itemNames[index];
        int quantity = itemQuantitiesValues[index];
        double price = itemPrices[index];

        // Check if the item already exists in the table
        boolean itemExists = false;
        for (OrderItem item : orderItems) {
            if (item.getName().equals(itemName)) {
                if (quantity > 0) {
                    // Update quantity if item exists and quantity > 0
                    item.setQuantity(quantity);
                } else {
                    // Remove item if quantity = 0
                    orderItems.remove(item);
                }
                itemExists = true;
                break;
            }
        }

        // If the item doesn't exist and quantity > 0, add it
        if (!itemExists && quantity > 0) {
            orderItems.add(new OrderItem(itemName, quantity, price));
        }

        // Refresh the table
        tableView.refresh();

        // Update total
        updateTotal();
    }

    private void updateTotal() {
        double total = 0;
        for (int i = 0; i < itemQuantitiesValues.length; i++) {
            total += itemQuantitiesValues[i] * itemPrices[i];
        }
        totalLabel.setText("Total: Rp " + String.format("%,.0f", total));
    }

    private void filterByCategory(String category) {
        // In a real application, you would filter the displayed items
        System.out.println("Filtering by: " + category);
    }

    private void updateTotals() {
        // Calculate totals from the current order items
        double amount = 0;
        for (OrderItem item : orderItems) {
            amount += item.getTotal();
        }

        double taxRate = 0.05; // 5% tax
        double tax = amount * taxRate;
        double total = amount + tax;

        amountLabel.setText("Rp. " + String.format("%,.0f", amount));
        taxLabel.setText(String.format("%.0f%%", taxRate * 100));
        totalLabel.setText("Rp. " + String.format("%,.0f", total));
    }

    @FXML
    private void processPesanan() {
        // Check if there are items in the order
        if (orderItems.isEmpty()) {
            Alert alert = new Alert(Alert.AlertType.WARNING);
            alert.setTitle("Empty Order");
            alert.setHeaderText("No Items in Order");
            alert.setContentText("Please add items to your order before processing.");
            alert.showAndWait();
            return;
        }

        // Check if payment method is selected
        if (paymentMethodLabel.getText().isEmpty()) {
            Alert alert = new Alert(Alert.AlertType.WARNING);
            alert.setTitle("Payment Method");
            alert.setHeaderText("No Payment Method Selected");
            alert.setContentText("Please select a payment method before processing.");
            alert.showAndWait();
            return;
        }

        // Process the order
        Alert alert = new Alert(Alert.AlertType.INFORMATION);
        alert.setTitle("Order Processed");
        alert.setHeaderText("Order Successfully Processed");
        alert.setContentText("Total: " + totalLabel.getText() + "\nPayment Method: " + paymentMethodLabel.getText());
        alert.showAndWait();

        // Reset quantities
        for (int i = 0; i < itemQuantitiesValues.length; i++) {
            itemQuantitiesValues[i] = 0;
            if (i < itemQuantities.length) {
                itemQuantities[i].setText("0");
            }
        }

        // Clear the table
        orderItems.clear();

        // Reset totals
        updateTotals();
    }

    // Model class for order items
    public static class OrderItem {
        private String name;
        private int quantity;
        private double price;

        public OrderItem(String name, int quantity, double price) {
            this.name = name;
            this.quantity = quantity;
            this.price = price;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public int getQuantity() {
            return quantity;
        }

        public void setQuantity(int quantity) {
            this.quantity = quantity;
        }

        public double getPrice() {
            return price;
        }

        public void setPrice(double price) {
            this.price = price;
        }

        public double getTotal() {
            return quantity * price;
        }
    }
}